import unittest
from qa_replay_oracle import assert_reextracted


def row(identifier, text, path="a.locres", **metadata):
    return {"id": identifier, "file_path": "C:/fixture/" + path, "source": text,
            "translation": text, "metadata": metadata}


# Literal expectations, not generated by the mirror. JA controls the physical
# width; the pivot's semantic English deliberately has a different width.
LAYOUT_CASES = [
    ("single-message", "msg", "森へ進む", "uno dos tres cuatro cinco seis siete ocho nueve diez",
     "uno dos tres cuatro cinco seis siete\nocho nueve diez"),
    ("provider-newlines", "msg", "森へ\n進む", "Hola\namigos del bosque", "Hola amigos del bosque"),
    ("name-spacing", "msg", r"\n<案内人>森へ進む", r"\n<Guía del bosque>   Hola amigos", r"\n<Guía del bosque>Hola amigos"),
    ("list", "msg", "・森へ\n・川へ", "・Bosque cercano ・Río lejano", "・Bosque cercano\n・Río lejano"),
    ("blanks", "msg", "\n森へ\n\n\n川へ\n", "Bosque\n\nRío", "\nBosque\n\n\nRío\n"),
    ("profile", "profile", "森へ進む道\n川へ進む道", "Un héroe del norte lejano", "Un\nhéroe\ndel\nnorte\nlejano"),
    ("profile-newlines-fit", "profile", "森へ進む道\n川へ進む道", "Uno\ndos", "Uno\ndos"),
    ("description", "description", "森へ進む道\n川へ進む道", "Uno dos tres", "Uno\ndos\ntres"),
    ("single-word-boundary", "profile", "森へ進む道\n川へ進む道", "extraordinario árbol", "extraordinario\nárbol"),
    ("dynamic-symbols", "msg", r"\C[2]森へ \V[1]\!", r"\C[2]Hola \V[1]\! amigos", r"\C[2]Hola \V[1]\! amigos"),
    ("literal-symbol", "msg", r"\c[27]森へ\c[0] \#", r"\c[27]Hola\c[0] \# amigos", r"\c[27]Hola\c[0] \# amigos"),
    ("embedded-name-controls", "msg", r"\n<\c[27]案内人\c[0]>森へ", r"\n<\c[27]Guía\c[0]>   Hola", r"\n<\c[27]Guía\c[0]>Hola"),
]


def layout_row(kind, physical, translation):
    identifier = ("Map001.json#event_1#page_0#cmd_1#msg" if kind == "msg"
                  else "Actors.json#1#" + kind)
    entry = row(identifier, "An English semantic source of deliberately different width", "data/Map001.json" if kind == "msg" else "data/Actors.json",
                format_id="rpgmaker-mv", locust_injection_source=physical)
    entry.update(translation=translation, tags=["dialogue" if kind == "msg" else "description"])
    return entry


def layout_rejections():
    original = layout_row("msg", r"\n<案内人>森へ \V[1]\!", r"\n<Guía>Hola \V[1]\! amigos")
    actual = dict(original, source=original["translation"])
    # Same ordered controls but displaced relative to the words must not pass.
    for text in (r"\n<Guía>\V[1]Hola \! amigos", r"\n<Guía>Hola \V[1] amigos\!",
                 r"\n<Guía>Hola \V[2]\! amigos", r"\n<Guía>Hola \V[1] amigos",
                 r"\n<Otra>Hola \V[1]\! amigos", r"\n<GuíaHola \V[1]\! amigos",
                 r"\n<Guía>Hola  \V[1]\! amigos", r"\n<Guía>Hola \V[1]\!amigos"):
        yield original, dict(actual, source=text)
    for text in (r"Hola \UNKNOWN[1]", r"Hola \C[\V[1]]", r"Hola \C[1", r"Hola \CC[1]", r"Hola \@", r"Hola \Garbage",
                 r"\n<>Hola", r"\n<  >Hola", r"\n<GuíaHola", r"\n<\UNKNOWN[1]Guía>Hola",
                 "Hola <b>amigos</b>", "Hola\x1camigos"):
        # Even exact equality cannot bypass independent syntax classification.
        malformed = layout_row("msg", text, text)
        yield malformed, dict(malformed, source=text)
    for changed in (dict(original, tags=["d_text"]), dict(original, tags=["unknown"]),
                    dict(original, metadata=dict(original["metadata"], format_id="unity"))):
        yield changed, dict(actual)
    yield original, dict(actual, tags=["scroll_text"])
    malformed_source = layout_row("msg", r"\n<案内人森へ", r"\n<Guía>Hola")
    yield malformed_source, dict(malformed_source, source=malformed_source["translation"])
    embedded = layout_row("msg", r"\n<\c[27]案内人\c[0]>森へ", r"\n<\c[27]Guía\c[0]>Hola")
    yield embedded, dict(embedded, source=r"\n<Guía>\c[27]\c[0]Hola")
    literal_symbol = layout_row("msg", r"\c[27]森へ\c[0] \#", r"\c[27]Hola\c[0] \# amigos")
    for text in (r"\c[27]Hola\c[0] amigos \#", r"\c[27]Hola\c[0] # amigos", r"\C[27]Hola\c[0] \# amigos"):
        yield literal_symbol, dict(literal_symbol, source=text)
    for index, corrupt in ((3, "・Bosque cercano\n■Río lejano"), (4, "Bosque\n\n\nRío\n")):
        _, kind, physical, literal, _ = LAYOUT_CASES[index]
        entry = layout_row(kind, physical, literal)
        yield entry, dict(entry, source=corrupt)


class OracleTests(unittest.TestCase):
    def check(self, expected, actual, engine="unreal"):
        return assert_reextracted(engine, expected, "C:/fixture", actual, "C:/fixture")

    def test_rejects_swapped_resources_even_with_identical_text_set(self):
        with self.assertRaises(AssertionError):
            self.check([row("one", "Hola"), row("two", "Adiós")], [row("one", "Adiós"), row("two", "Hola")])

    def test_rejects_missing_duplicate_text_resource(self):
        with self.assertRaises(AssertionError):
            self.check([row("one", "Hola"), row("two", "Hola")], [row("one", "Hola")])

    def test_rejects_wrong_file_and_extra_backup_rows(self):
        original = [row("one", "Hola")]
        for extracted in ([row("one", "Hola", "b.locres")], original + [row("one", "Hola", ".locust/backup/a.locres")]):
            with self.assertRaises(AssertionError):
                self.check(original, extracted)

    def test_html_offset_growth_keeps_element_order_and_kind(self):
        original = [row("a#html:10", "Hola", "a.html", html_start=10, html_kind="text:p"), row("a#html:20", "Adiós", "a.html", html_start=20, html_kind="text:p")]
        extracted = [row("a#html:10", "Hola", "a.html", html_start=10, html_kind="text:p"), row("a#html:99", "Adiós", "a.html", html_start=99, html_kind="text:p")]
        self.assertEqual(self.check(original, extracted, "html-game")["resources_verified"], 2)
        extracted[1]["source"] = "Hola"
        with self.assertRaises(AssertionError):
            self.check(original, extracted, "html-game")

    def test_rpg_growth_changes_offsets_but_not_dialogue_identity(self):
        original = [layout_row("msg", "森へ進む", LAYOUT_CASES[0][3]), row("Map#event_1#page_0#cmd_2#msg", "Goodbye")]
        extracted = [dict(original[0], source=LAYOUT_CASES[0][4]), row("Map#event_1#page_0#cmd_3#msg", "Goodbye")]
        self.assertEqual(self.check(original, extracted, "rpgmaker-mv")["normalized_rpg_dialogues"], 1)
        extracted[1]["id"] = "Map#event_2#page_0#cmd_3#msg"
        with self.assertRaises(AssertionError):
            self.check(original, extracted, "rpgmaker-mv")

    def test_exact_writer_layouts_and_corruptions(self):
        for label, kind, physical, literal, written in LAYOUT_CASES:
            with self.subTest(label=label):
                original = layout_row(kind, physical, literal)
                actual = dict(original, source=written)
                result = self.check([original], [actual], "rpgmaker-mv")
                self.assertEqual(result["resources_verified"], 1)
                for corrupt in (written + " ", written.replace(" ", "  ", 1),
                                written + ".", written + "otro", written.replace("\n", " ", 1)):
                    if corrupt != written:
                        with self.subTest(corrupt=corrupt), self.assertRaises(AssertionError):
                            self.check([original], [dict(actual, source=corrupt)], "rpgmaker-mv")

    def test_controls_tags_lists_blanks_and_positions_remain_strict(self):
        for original, actual in layout_rejections():
            with self.subTest(actual=actual), self.assertRaises(AssertionError):
                self.check([original], [actual], "rpgmaker-mv")

    def test_alternate_layout_branches(self):
        for kind, physical, literal, written in (
            ("msg", "森へ\n\n川へ", "Uno dos tres", "Uno dos tres"),  # ambiguous paragraph mapping
            ("profile", "森へ\n\n川へ", "Uno dos tres", "Uno\ndos\ntres"),
            ("profile", "\n\n", "Uno dos tres", "Uno dos tres"),  # zero source width
            ("profile", "森へ\n進む", "Uno\r\ndos", "Uno\ndos"),  # CRLF, overflow
            ("msg", "森へ\n\n川へ\n", "森へ\n\n川へ\n", "森へ\n\n川へ\n"),  # unchanged skip
            ("msg", "森" * 48, "uno dos tres cuatro cinco seis siete ocho nueve diez", "uno dos tres cuatro cinco seis siete ocho nueve\ndiez"),
            ("profile", "森へ進む道\n川へ進む道", "áéí 😀 yo", "áéí 😀\nyo"),  # Rust scalar lengths, not UTF-16
            ("profile", "森へ\n川へ", r"\# x", "\\#\nx"),  # literal '#' has width one
            ("msg", r"\#森へ", "Hola", "Hola"),  # source literal is not a protected escape
        ):
            original = layout_row(kind, physical, literal)
            with self.subTest(kind=kind, physical=physical):
                self.check([original], [dict(original, source=written)], "rpgmaker-mv")

    def test_arbitrary_breaks_and_unsupported_slots_are_not_layout(self):
        for engine, kind, physical, literal, actual in (
            ("rpgmaker-mv", "msg", "森へ\n進む", "Hola amigos", "Hola\namigos"),
            ("rpgmaker-mv", "name", "森へ\n進む", "Hola amigos", "Hola\namigos"),
            ("rpgmaker-mv", "choice_0", "森へ\n進む", "Hola amigos", "Hola\namigos"),
            ("renpy", "msg", "森へ\n進む", "Hola amigos", "Hola\namigos"),
        ):
            original = layout_row(kind, physical, literal)
            with self.subTest(engine=engine, kind=kind), self.assertRaises(AssertionError):
                self.check([original], [dict(original, source=actual)], engine)

    def test_rpg_choices_share_command_but_keep_choice_identity(self):
        original = [row("Map#event_1#page_0#cmd_2#choice_0", "Sí"), row("Map#event_1#page_0#cmd_2#choice_1", "No")]
        self.assertEqual(self.check(original, original, "rpgmaker-mv")["resources_verified"], 2)
        with self.assertRaises(AssertionError):
            self.check(original, [original[0], original[0]], "rpgmaker-mv")


if __name__ == "__main__":
    unittest.main()
